pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed: amount to deposit and whether recipient will revert (as uint8 flag)
    function testFuzz_property(uint256 depositAmount, address ownerLike) public {
        // Keep domain sensible but wide
        vm.assume(depositAmount <= 1 ether);
        // Deploy a malicious recipient that reverts on receive/fallback
        Reverter reverter = new Reverter();

        // fund the contract C by sending ether to its fallback (which increments depositsCount)
        vm.deal(address(this), depositAmount);
        // send funds to c so it has balance
        if (depositAmount > 0) {
            // send via call to trigger fallback payable
            (bool s,) = address(c).call{value: depositAmount}("");
            require(s);
        }

        // make sure c has the expected balance before withdrawAll
        assert(address(c).balance == depositAmount);

        // now act as the owner (c.owner is set to deployer in setUp, which is address(this))
        // call withdrawAll but route recipient as the reverter contract by making msg.sender be the Reverter
        // To cause the mutated direct transfer to attempt sending to a contract that reverts, we need msg.sender to be that contract.
        // We simulate the owner being the reverter by impersonation and calling withdrawAll as the reverter.

        vm.prank(address(reverter));
        // transfer some funds to reverter so it can be owner in this context (not strictly required, but keep realistic)
        vm.deal(address(reverter), 0);

        // perform withdrawAll as if owner = reverter
        bool ok;
        try C(address(c)).withdrawAll{value:0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after withdrawAll completes (either success or revert),
        // in the correct implementation calling withdrawAll as owner who may be a contract that reverts on receive,
        // the contract's balance must be zero (the internal withdraw path ensures clearing). The mutant can leave funds or revert.
        // We therefore assert that c.balance == 0. This holds for the reference for all inputs, but the mutant will fail for some input (when the recipient reverts).
        assertTrue(address(c).balance == 0);
    }
}

// adversarial helper that reverts on receive/call
contract Reverter {
    fallback() external payable {
        revert("nope");
    }
    receive() external payable {
        revert("nope");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit, and a boolean deciding whether recipient will revert
    function testFuzz_property(uint256 depositAmount, bool doRevert) public {
        // keep depositAmount in a reasonable wide range but non-zero
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy an adversarial recipient that optionally reverts on receive
        AttackerRecipient rec = new AttackerRecipient(doRevert);

        // fund the contract C by sending ETH to its fallback (counts depositsCount++)
        vm.deal(address(this), depositAmount);
        // send ether to C so its balance increases
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        // ensure c has the expected balance before withdrawAll
        assert(address(c).balance == depositAmount);

        // make this contract the owner when c was deployed (setUp used msg.sender==address(this))
        // call withdrawAll as the owner; route the withdrawal to the attacker recipient by making
        // the owner be the recipient via a crafted flow: we need msg.sender to be the recipient
        // So we have the owner (this) call a helper that will in turn call c.withdraw and cause
        // funds to be forwarded to msg.sender (owner). But withdrawAll in reference calls withdraw(address(this).balance)
        // which will ultimately transfer to payable(msg.sender) (owner). To observe difference between
        // internal-call-based path and direct transfer in mutant, we instead make the owner be the rec
        // by impersonating rec when calling withdrawAll.

        // Give rec some ETH so it can be the msg.sender (prank will make msg.sender == rec)
        vm.deal(address(rec), 1);

        // Now call withdrawAll with msg.sender == rec (so payable(msg.sender) is rec in the withdraw path)
        vm.prank(address(rec));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the reference contract, withdrawAll always empties C's balance
        // regardless of whether the recipient reverts on receive; the mutated version can leave funds.
        // We assert that c's balance is zero here; this holds for the reference implementation for all inputs
        // and is violated by the mutant for some inputs (when doRevert == true).
        assertTrue(address(c).balance == 0);
    }
}

// Adversarial recipient: can be set to revert on receive
contract AttackerRecipient {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    fallback() external payable {
        if (shouldRevert) revert("bad");
    }
    receive() external payable {
        if (shouldRevert) revert("bad");
    }
}

