pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to deposit (uint256) and whether the adversarial helper will revert on receive (bool)
    function testFuzz_property(uint256 amt, bool makeRevert) public {
        // Keep amount within reasonable bounds so vm.deal works and we don't overflow gas in tests
        amt = bound(amt, 1, 1 ether);

        // Deploy adversarial helper that may revert on receive depending on makeRevert
        Adversary adv = new Adversary(makeRevert);

        // Fund the adversary so it can be the msg.sender/owner when needed
        vm.deal(address(adv), amt);

        // Make the adversary the owner by having it deploy or call C constructor? The contract C sets owner = msg.sender at construction.
        // But c is already deployed with test contract as owner. We need owner to be able to call withdrawAll — keep test contract as owner.
        // The scenario is: deposit into c by sending ETH from this test contract via adversary as recipient of future transfer.

        // Send ETH into c so c has balance. Use vm.prank to make this contract send
        vm.deal(address(this), amt);
        // Deposit by sending directly to fallback()
        (bool ok,) = address(c).call{value: amt}("");
        require(ok);

        // Sanity: c should have the deposited balance
        assert(address(c).balance == amt);

        // Now we want to make msg.sender in withdrawAll be the owner (this test contract). The internal withdraw will send to payable(msg.sender).
        // But when sending out from C, the recipient can be an address that reverts on receive only if that recipient is msg.sender.
        // To create difference between internal call vs direct transfer, we will make the owner be the adversarial contract by transferring ownership in-place is not possible.
        // Instead, simulate the adversarial behaviour by having the owner (this test contract) call sendMoney to cause C to call the adversary with data/value, ensuring the adversary's fallback may revert in other flows.
        // However the distinguishing change described affects only withdrawAll: the reference calls withdraw(address(this).balance) which does payable(msg.sender).transfer(_value) inside withdraw; the mutant replaces the withdrawAll call with direct transfer to msg.sender. The difference surfaces when msg.sender is a contract that reverts on receive.

        // Therefore we need the owner to be a contract that can revert on receive. Currently owner is this test contract (EOA-like). To make owner the adversary, we must deploy C with adv as constructor sender — but setUp already deployed C. To satisfy constraints, we instead re-deploy C with adv as deployer here.
        C c2 = deployCFrom(address(adv));

        // Fund c2 by sending amt to its fallback from this test
        vm.deal(address(this), amt);
        (bool ok2,) = address(c2).call{value: amt}("");
        require(ok2);
        assert(address(c2).balance == amt);

        // Now adv is the owner of c2. Have adv call withdrawAll on c2. adv will attempt to receive the transfer when withdrawAll executes in the mutant path.
        // Execute the call as adv
        vm.prank(address(adv));
        bool okCall;
        try c2.withdrawAll() {
            okCall = true;
        } catch {
            okCall = false;
        }

        // The general property we assert on the reference C (deployed as c2 by adv) is: after withdrawAll, c2.balance == 0
        // This holds for the reference for all admissible inputs (amt in [1,1 ether], adv configured true/false). The mutant that directly does transfer in withdrawAll will revert or leave balance non-zero when adv reverts on receive (makeRevert == true) for some amt. We assert the reference property by observing c2.balance.
        assertTrue(address(c2).balance == 0);
    }

    // Helper to deploy C with a specified deployer address by using create2 proxy deploy via this test; we simulate deployment from another address by using a factory contract deployed then called by that address.
    function deployCFrom(address deployer) internal returns (C) {
        // We deploy a tiny factory to deploy C while being called by deployer via vm.prank
        Factory f = new Factory();
        vm.prank(deployer);
        address caddr = f.deployC();
        return C(payable(caddr));
    }
}

contract Factory {
    function deployC() external returns (address) {
        C c = new C();
        return address(c);
    }
}

// Adversary contract: optionally reverts in receive()
contract Adversary {
    bool public shouldRevert;
    constructor(bool _r) payable {
        shouldRevert = _r;
    }
    receive() external payable {
        if (shouldRevert) revert("receive revert");
    }
}

