pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the incoming deposit amount (must be > 0 to detect the bug)
    function testFuzz_property(uint256 deposit) public {
        // keep deposit in a wide admissible range but require it > 0
        deposit = bound(deposit, 0, 1 ether);
        vm.assume(deposit > 0);

        // owner is the test contract (deployed C sets owner = msg.sender in setUp)
        // fund this contract so it can send ETH into c
        vm.deal(address(this), deposit);

        // send ETH to c triggering its fallback which increments depositsCount and increases balance
        // call as this contract
        (bool suc, ) = address(c).call{value: deposit}("");
        require(suc, "deposit call failed");

        uint256 before = address(c).balance;
        // sanity: before should equal deposit
        // drive withdrawAll as owner
        c.withdrawAll();
        uint256 after = address(c).balance;

        // General rule: for any positive prior balance, withdrawAll reduces contract balance.
        // This will hold for the reference implementation (withdraws full balance) and fail for the mutant that calls withdraw(0).
        assertTrue(after < before);
    }
}

