pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = address(this); }

    // fuzz parameters: an arbitrary positive deposit amount and an arbitrary attacker address
    function testFuzz_property(uint256 depositAmount) public {
        // keep depositAmount in a wide but meaningful domain (at least 1 wei and not absurdly huge)
        depositAmount = bound(depositAmount, 1, 1 ether);

        // fund this test contract (the owner) so it can send eth to c
        vm.deal(address(this), depositAmount);

        // send depositAmount to c via its fallback by doing a plain call with value
        // the fallback increments depositsCount and increases address(c).balance
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        // record balance before withdrawAll
        uint256 beforeBalance = address(c).balance;

        // as owner (this contract is the owner by construction), call withdrawAll
        c.withdrawAll();

        // record balance after withdrawAll
        uint256 afterBalance = address(c).balance;

        // General rule: for any owner and any positive contract balance, withdrawAll sends out the full balance,
        // so address(c).balance must strictly decrease (be zero) after withdrawAll. The mutant calling withdraw(0)
        // can leave the balance unchanged; thus we assert the correct contract's balance decreased.
        assertTrue(afterBalance < beforeBalance);
    }
}

