pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to fund the contract (must be > 0) and a non-owner actor (unused here but kept
    // to obey fuzzing rule of taking parameters); we use only amount and the owner's msg.sender is the test contract
    function testFuzz_property(uint256 fundAmount, address other) public {
        // Keep fundAmount in a wide admissible domain but require positive amount so withdrawAll should have an effect
        fundAmount = bound(fundAmount, 1, type(uint128).max); // wide, positive

        // Ensure other is some arbitrary address but not used as owner; keep it unconstrained otherwise
        vm.assume(other != address(0));

        // Fund the contract from this test contract (which is the owner because setUp deployed c)
        vm.deal(address(this), fundAmount);
        // Call fallback by sending funds to trigger depositsCount++ (not necessary but ensures contract holds balance)
        // Send funds directly to contract
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Record balance before withdrawAll
        uint256 before = address(c).balance;

        // The reference implementation should transfer the full balance when owner calls withdrawAll.
        // Call as owner (this contract is owner because it deployed c in setUp)
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: after owner calls withdrawAll, the contract balance must be strictly less than before
        // (Reference: withdrawAll sends full balance; Mutant: withdrawAll calls withdraw(0) and may leave balance unchanged)
        assertTrue(ok && address(c).balance < before);
    }
}

