import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to fund the contract and the caller address (will be owner)
    function testFuzz_property(uint256 fundAmount, address caller) public {
        // keep fundAmount in a reasonable nonzero range (wide) and caller nonzero
        fundAmount = bound(fundAmount, 1, type(uint128).max);
        vm.assume(caller != address(0));

        // Make 'caller' be the owner of c by using the deployed owner (c's owner is deployer in setUp)
        // The contract's owner is address(this) because setUp deployed c from this test contract.
        // So we must have the owner call withdrawAll: use address(this) as caller.
        // Ensure we interpret the fuzzed 'caller' as an external funder (not the owner) who sends funds in.

        // Fund the contract from the external fuzzed caller
        vm.deal(caller, fundAmount);
        vm.prank(caller);
        // send Ether to contract, triggering fallback and increasing depositsCount
