        // Now the owner (this test contract) calls withdrawAll
        // Record balance before and call
        uint before = address(c).balance;
        // as owner, call withdrawAll
        c.withdrawAll();
        uint after = address(c).balance;

        // General rule: after the owner calls withdrawAll, the contract balance is zero
        // (the reference C sends the full balance; the mutant that calls withdraw(0) will violate this for some inputs)
        assertTrue(after == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to fund the contract and an address that will be the owner (msg.sender)
    function testFuzz_property(uint256 fundAmount, address ownerAddr) public {
        // keep fundAmount in a wide admissible range but non-zero to allow the distinction
        fundAmount = bound(fundAmount, 0, type(uint128).max);

        // ownerAddr must be a non-zero address
        vm.assume(ownerAddr != address(0));

        // fund the ownerAddr with enough ETH to send into the contract
        vm.deal(ownerAddr, fundAmount + 1 ether);

        // make ownerAddr the deployer/owner of a fresh contract c2 to simulate arbitrary owner
        // but requirement: we MUST use the c deployed in setUp(), whose owner is the test contract deployer (address(this)).
        // To make ownerAddr the caller of withdrawAll on c, ownerAddr must equal the recorded owner in c.
        // The contract C sets owner = msg.sender at construction, so only address(this) is owner. To let ownerAddr act as owner,
        // we will instead have address(this) be the owner and perform actions as address(this). The fuzzed ownerAddr will act as the funder only.

        // fund the contract c by having ownerAddr send fundAmount via a low-level call to trigger fallback
        if (fundAmount > 0) {
            vm.prank(ownerAddr);
            // send ETH to c. fallback increments depositsCount but that's irrelevant; it increases address(c).balance
            (bool s,) = address(c).call{value: fundAmount}("");
            assertTrue(s);
        }

        // Record balances before withdrawAll: owner (address(this)) and contract
        uint256 ownerBefore = address(this).balance;
        uint256 contractBefore = address(c).balance;

        // owner (address(this)) calls withdrawAll
        // call may revert if onlyOwner fails, but here address(this) is the owner so it should not revert
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: if the contract had some balance and the owner calls withdrawAll successfully,
        // the owner's balance should increase exactly by the previous contract balance (i.e., contractBefore).
        // We express this as: if the call succeeded, ownerAfter - ownerBefore == contractBefore
        uint256 ownerAfter = address(this).balance;

        // Single assertion: if the call succeeded then the owner received exactly the contract's previous balance
        assertTrue(!ok || (ownerAfter - ownerBefore == contractBefore));
    }
}

